qs_rules() {
  QS_FIRED=0
  if q_rule_ready 0 && { { q_exists 'mailbox/spare-key.txt' && ! q_exists 'hallway/spare-key.txt'; }; }; then
    q_rule_mark 0
    QS_FIRED=1
    q_say 'Hmm: you MOVED your only key to the mailbox. mv moves a thing; cp makes a copy and leaves the first one where it was. Move it back and copy it instead.'
  fi
  if q_rule_ready 1 && { { q_exists 'todo.txt' && ! { q_contains 'todo.txt' 'find the remote'; }; }; }; then
    q_rule_mark 1
    QS_FIRED=1
    q_say 'Uh oh: the old to-do list is gone. Writing with > (or Set-Content) replaces a whole file; >> (or Add-Content) adds to the end. Lesson learned, and no harm done this time.'
  fi
}

