qs_goal_teach() {
  case "$1" in
    'list')
      q_say 'head shows the first 10 lines of a file, so you get the important part of a long file without scrolling. head -n 3 shows just 3. Its partner, tail, shows the last lines.'
      ;;
    'shelf')
      q_say 'mkdir makes a new folder ("make directory"). mkdir living-room/bookshelf makes a folder called bookshelf inside the living room.'
      ;;
    'books')
      q_say 'mv moves things: mv WHAT WHERE. A * is a wildcard: it stands for "anything", so hallway/box-books/*.book means every file in that box ending in .book. One command moves all four.'
      ;;
    'kitchen')
      q_say 'A * on its own means everything in a folder. mv hallway/box-kitchen/* kitchen/ empties the whole box into the kitchen.'
      ;;
    'key')
      q_say 'cp copies: the key ends up in the mailbox AND stays in the hallway. mv would have moved your only key.'
      ;;
    'trash')
      q_say 'rm removes files, and you can name several at once. Careful: there is no recycle bin in a terminal. Removed means gone.'
      ;;
    'boxes')
      q_say 'rmdir removes a folder, but only an empty one: a safety catch. The book box and the kitchen box are empty now. (rm -r removes a folder and everything in it, so double-check before you use it.)'
      ;;
    'sign')
      q_say 'echo prints words; > sends them into a file instead of the screen, making the file. echo "Welcome to my place" > door-sign.txt makes your sign. (Careful: > replaces whatever the file had.)'
      ;;
    'todo')
      q_say '>> adds to the end of a file and keeps what was there. One > would have wiped the list: two of them append.'
      ;;
  esac
}

