qs_goal_solution() {
  case "$1" in
    'list')
      printf '%s\n' 'head hallway/packing-list.txt'
      ;;
    'shelf')
      printf '%s\n' 'mkdir living-room/bookshelf'
      ;;
    'books')
      printf '%s\n' 'mv hallway/box-books/*.book living-room/bookshelf/'
      ;;
    'kitchen')
      printf '%s\n' 'mv hallway/box-kitchen/* kitchen/'
      ;;
    'key')
      printf '%s\n' 'cp hallway/spare-key.txt mailbox/'
      ;;
    'trash')
      printf '%s\n' 'rm hallway/broken-vase.txt hallway/bubble-wrap.txt'
      ;;
    'boxes')
      printf '%s\n' 'rmdir hallway/box-books hallway/box-kitchen'
      ;;
    'sign')
      printf '%s\n' 'echo "Welcome to my place" > door-sign.txt'
      ;;
    'todo')
      printf '%s\n' 'echo "- water the plants" >> todo.txt'
      ;;
  esac
}

